CREATE TYPE "main"."moduleType" AS ENUM ('IB0', 'IB1', 'IB2');

CREATE TABLE "main"."Module" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "modType" main."moduleType" NOT NULL,
  "serialNumber" varchar(50) UNIQUE NOT NULL,
  "generalLocation" main."wpGeneralLocation" NOT NULL
);

CREATE TABLE "main"."ModuleChipList" (
  "modId" integer NOT NULL,
  "chipId" integer NOT NULL,
  PRIMARY KEY ("modId", "chipId")
);

CREATE TABLE "main"."ModuleLocation" (
  "modId" integer NOT NULL,
  "generalLocation" main."wpGeneralLocation" NOT NULL,
  "date" date DEFAULT (CURRENT_DATE),
  "username" varchar(50),
  "note" text
);

ALTER TABLE "main"."ModuleChipList" ADD FOREIGN KEY ("modId") REFERENCES "main"."Module" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "main"."ModuleChipList" ADD FOREIGN KEY ("chipId") REFERENCES "main"."Chip" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "main"."ModuleLocation" ADD FOREIGN KEY ("modId") REFERENCES "main"."Module" ("id") DEFERRABLE INITIALLY IMMEDIATE;
